package ru.cherdakmd.chrdkregister;

import com.google.gson.*;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.io.TempDir;
import ru.cherdakmd.chrdkregister.api.*;
import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import java.util.logging.Logger;
import static org.junit.jupiter.api.Assertions.*;

class ShopNativeBankTest {
    @TempDir Path dir;
    final UUID owner=UUID.randomUUID(),market=UUID.randomUUID(),other=UUID.randomUUID();
    final Logger log=Logger.getAnonymousLogger();
    BankStore load() { var b=new BankStore(dir,log); b.load(); return b; }
    BankStore funded(long amount) { var b=load(); b.deposit(owner,"Steve",amount); assertTrue(b.registerShop(market)); return b; }
    ShopExchange trade(boolean buy,long debit,long credit,long physical,long seq) { return new ShopExchange(UUID.randomUUID(),market,seq,owner,buy,"STONE",64,10,debit,credit,physical,Map.of("DIAMOND",1,"DIAMOND_BLOCK",9),"before","after"); }
    InventoryTransferTest.Bag bag() { return new InventoryTransferTest.Bag(owner); }
    @Test void bankReservationIsCanonicalBeforeAnyBuyGrant() { var b=funded(100); var t=trade(true,10,0,0,1); assertTrue(b.prepareShop(t,"Steve")); assertEquals(100,load().balance(owner)); assertTrue(load().cashLocked(owner)); assertEquals(ShopExchange.Status.PREPARED,load().shopStatus(t)); }
    @Test void buyDebitAndMarketReceiptPublishOnlyAfterNativeProof() throws Exception { var b=funded(100); var t=trade(true,10,0,0,1); b.prepareShop(t,"Steve"); var bag=bag(); assertEquals(InventoryTransfer.Decision.APPLIED,BankCash.recover(b,owner,bag)); assertEquals(90,load().balance(owner)); assertEquals(ShopExchange.Status.COMMITTED,load().shopStatus(t)); assertEquals(1,bag.applies); }
    @Test void saleIncomeIsNotSpendableBeforeNativeConsume() throws Exception { var b=funded(100); var t=trade(false,0,10,0,1); b.prepareShop(t,"Steve"); assertEquals(100,b.balance(owner)); assertFalse(b.withdraw(owner,1)); BankCash.recover(b,owner,bag()); assertEquals(110,load().balance(owner)); }
    @Test void physicalOnlyBuyWithZeroBankDeltaStillHasARealReservationAndReceipt() throws Exception { var b=funded(0); var t=trade(true,0,0,10,1); assertTrue(b.prepareShop(t,"Steve")); assertTrue(b.cashLocked(owner)); BankCash.recover(b,owner,bag()); assertEquals(0,load().balance(owner)); assertEquals(ShopExchange.Status.COMMITTED,load().shopStatus(t)); }
    @Test void changeFromBlocksIsGrantedOnceToBank() throws Exception { var b=funded(2); var t=trade(true,2,1,9,1); b.prepareShop(t,"Steve"); var bag=bag(); BankCash.recover(b,owner,bag); BankCash.recover(load(),owner,bag); assertEquals(1,load().balance(owner)); assertEquals(2,load().account(owner).withdrawn); assertEquals(3,load().account(owner).deposited); assertEquals(1,bag.applies); }
    @Test void completedMarketReceiptSurvivesNewOrdinaryCashReceiptAndSpending() throws Exception { var b=funded(100); var t=trade(true,10,0,0,1); b.prepareShop(t,"Steve"); var bag=bag(); BankCash.recover(b,owner,bag); b.withdraw(owner,80); b.flush(); bag.state="before"; b.prepareCash(owner,"Steve",BankCash.Kind.DEPOSIT,1,9,-1,1,"before","after"); BankCash.recover(b,owner,bag); assertEquals(ShopExchange.Status.COMMITTED,load().shopStatus(t)); assertEquals(11,load().balance(owner)); }
    @Test void wrongLineageOrMissingRegistrationNeverMeansMissingReceipt() { var b=load(); var t=trade(true,10,0,0,1); assertEquals(ShopExchange.Status.UNAVAILABLE,b.shopStatus(t)); assertTrue(b.registerShop(UUID.randomUUID())); assertFalse(b.registerShop(market)); assertEquals(ShopExchange.Status.UNAVAILABLE,b.shopStatus(t)); }
    @Test void secondOwnerCannotCreateAnotherPendingForSameMarketSequence() { var b=funded(100); var first=trade(true,10,0,0,1); b.prepareShop(first,"Steve"); var second=new ShopExchange(UUID.randomUUID(),market,1,other,false,"STONE",64,10,0,10,0,Map.of("DIAMOND",1),"before","after"); assertEquals(ShopExchange.Status.CONFLICT,b.shopStatus(second)); assertFalse(b.prepareShop(second,"Other")); assertEquals(5,b.deposit(other,"Other",5)); }
    @Test void alteredOrSkippedMarketSequenceCannotReplayOldReceipt() throws Exception { var b=funded(100); var t=trade(true,10,0,0,1); b.prepareShop(t,"Steve"); BankCash.recover(b,owner,bag()); assertEquals(ShopExchange.Status.CONFLICT,b.shopStatus(trade(true,10,0,0,1))); assertEquals(ShopExchange.Status.CONFLICT,b.shopStatus(trade(true,10,0,0,3))); assertEquals(ShopExchange.Status.MISSING,b.shopStatus(trade(true,10,0,0,2))); }
    @Test void capAndInsufficientBalanceRefuseWithoutReservation() { var b=funded(BankStore.MAX_BALANCE); assertFalse(b.prepareShop(trade(false,0,10,0,1),"Steve")); assertFalse(b.cashLocked(owner)); b.setBalance(owner,"Steve",1); assertFalse(b.prepareShop(trade(true,10,0,0,1),"Steve")); }
    @Test void afterSnapshotWithoutNonceDoesNotSettleMarket() throws Exception { var b=funded(100); var t=trade(true,10,0,0,1); b.prepareShop(t,"Steve"); var bag=bag(); bag.state="after"; assertEquals(InventoryTransfer.Decision.CONFLICT,BankCash.recover(b,owner,bag)); assertEquals(ShopExchange.Status.PREPARED,b.shopStatus(t)); assertEquals(100,b.balance(owner)); }
    @Test void failedPlayerdataSaveAndInMemoryNonceRequireSuccessfulCurrentCheckpoint() throws Exception { var b=funded(100); var t=trade(true,10,0,0,1); b.prepareShop(t,"Steve"); var bag=bag(); bag.failSave=true; assertThrows(IOException.class,()->BankCash.recover(b,owner,bag)); assertThrows(IOException.class,()->BankCash.recover(b,owner,bag)); assertEquals(ShopExchange.Status.PREPARED,b.shopStatus(t)); bag.failSave=false; BankCash.recover(load(),owner,bag); assertEquals(ShopExchange.Status.COMMITTED,load().shopStatus(t)); assertEquals(1,bag.applies); }
    @Test void prepareBeforeRenameFailureHasNoNativeEffectOrReceipt() throws Exception { funded(100); Files.createDirectory(dir.resolve("bank.json.tmp")); var b=load(); var t=trade(true,10,0,0,1); assertFalse(b.prepareShop(t,"Steve")); assertFalse(b.available()); assertEquals(ShopExchange.Status.MISSING,load().shopStatus(t)); }
    @Test void prepareAfterRenameFailureLeavesRecoverableCanonicalIntent() throws Exception { funded(100); var b=new BankStore(dir,log,()->{throw new IOException("prepare uncertain");}); b.load(); var t=trade(true,10,0,0,1); assertFalse(b.prepareShop(t,"Steve")); b.flush(); assertEquals(ShopExchange.Status.PREPARED,load().shopStatus(t)); BankCash.recover(load(),owner,bag()); assertEquals(90,load().balance(owner)); }
    @Test void finishAfterRenameFailureNeverSeparatesMarketReceiptFromBalance() throws Exception { var b=funded(100); var t=trade(true,10,0,0,1); b.prepareShop(t,"Steve"); var failed=new BankStore(dir,log,()->{throw new IOException("finish uncertain");}); failed.load(); var bag=bag(); assertEquals(InventoryTransfer.Decision.WAIT,BankCash.recover(failed,owner,bag)); assertFalse(failed.available()); failed.flush(); assertEquals(ShopExchange.Status.COMMITTED,load().shopStatus(t)); assertEquals(90,load().balance(owner)); assertNull(load().cashPending(owner)); }
    @Test void finishBeforeRenameFailureRetainsReservationAndDoesNotRepeatNativeGrant() throws Exception { var b=funded(100); var t=trade(true,10,0,0,1); b.prepareShop(t,"Steve"); Files.createDirectory(dir.resolve("bank.json.tmp")); var bag=bag(); assertEquals(InventoryTransfer.Decision.WAIT,BankCash.recover(b,owner,bag)); assertEquals(ShopExchange.Status.PREPARED,load().shopStatus(t)); Files.delete(dir.resolve("bank.json.tmp")); BankCash.recover(load(),owner,bag); assertEquals(1,bag.applies); assertEquals(90,load().balance(owner)); }
    @Test void importReceiptIsDurableBeforePreparingTheSourceJournal() { var b=load(); assertTrue(b.importLegacyShop(owner,13)); assertTrue(load().legacyShopImported(owner)); assertEquals(13,load().balance(owner)); assertTrue(load().importLegacyShop(owner,1)); assertEquals(13,load().balance(owner)); }
    @Test void ambiguousImportDoesNotLoseItsReceiptOrImportTwice() { var b=new BankStore(dir,log,()->{throw new IOException("import uncertain");}); assertFalse(b.importLegacyShop(owner,13)); assertFalse(b.available()); b.flush(); assertTrue(load().legacyShopImported(owner)); assertTrue(load().importLegacyShop(owner,13)); assertEquals(13,load().balance(owner)); }
    @Test void schemaFiveMigratesButCannotHideNewMarketReceipts() throws Exception { var b=funded(100); var json=JsonParser.parseString(Files.readString(b.file())).getAsJsonObject(); json.addProperty("schema",5); json.remove("shopSettlements"); json.remove("claimSettlements"); Files.writeString(b.file(),json.toString()); assertTrue(load().available()); assertTrue(load().prepareShop(trade(true,10,0,0,1),"Steve")); json=JsonParser.parseString(Files.readString(b.file())).getAsJsonObject(); json.addProperty("schema",5); String bad=json.toString(); Files.writeString(b.file(),bad); b=load(); assertFalse(b.available()); b.flush(); assertEquals(bad,Files.readString(b.file())); }
    @Test void malformedTypedShopCountersAreNotCoerced() throws Exception { var b=funded(100); b.prepareShop(trade(true,10,0,0,1),"Steve"); String original=Files.readString(b.file()); for(String bad:List.of("\"1\"","1.5","9223372036854775808")) { var json=JsonParser.parseString(original).getAsJsonObject(); json.getAsJsonObject("cashPending").getAsJsonObject(owner.toString()).getAsJsonObject("shop").add("money",JsonParser.parseString(bad)); Files.writeString(b.file(),json.toString()); var loaded=load(); assertFalse(loaded.available()); loaded.flush(); assertEquals(json.toString(),Files.readString(b.file())); } }
    @Test void ratesRemainImmutableAndCustomWholeCurrencyIsFrozen() { var rates=new HashMap<String,Integer>(); rates.put("DIAMOND_BLOCK",100); var t=new ShopExchange(UUID.randomUUID(),market,1,owner,true,"STONE",64,10,0,90,100,rates,"before","after"); rates.clear(); assertTrue(t.valid()); assertThrows(UnsupportedOperationException.class,()->t.rates().clear()); assertEquals(100,t.rates().get("DIAMOND_BLOCK")); }
    @Test void invalidArithmeticAndSnapshotsAreRefusedBeforePrepare() { assertFalse(trade(true,10,1,0,1).valid()); assertFalse(trade(false,1,10,0,1).valid()); assertFalse(trade(true,0,0,0,1).valid()); assertFalse(trade(true,10,0,0,0).valid()); }
    @Test void nativeWiringReconstructsPlanAndUsesCanonicalCashCheckpoint() throws Exception { String service=Files.readString(Path.of("src/main/java/ru/cherdakmd/chrdkregister/BankService.java")); assertTrue(service.contains("ShopInventory.valid(t)")); assertTrue(service.contains("store.prepareShop(t,player.getName())")); assertTrue(service.contains("recoverCash(player)")); String plan=Files.readString(Path.of("src/main/java/ru/cherdakmd/chrdkregister/api/ShopInventory.java")); assertFalse(plan.contains("dropItem")); assertTrue(plan.contains("!i.hasItemMeta()")); assertTrue(plan.contains("ChargeInventory.matches(items,t.after())")); }
}
